begin;
do $$
declare sid uuid:=gen_random_uuid();boss uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();owner_id uuid;c uuid;l uuid;d uuid;wa uuid;wb uuid;s1 uuid;s2 uuid;open_shift uuid;r uuid;denied boolean;report jsonb;v_ids uuid[];v_retry uuid[];v_req uuid:=gen_random_uuid();v_pair jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at) values(boss,boss||'@test.invalid',now()),(a,a||'@test.invalid',now()),(b,b||'@test.invalid',now());
 perform set_config('request.jwt.claim.sub',boss::text,true);c:=public.create_company_for_edition('Shift workflow acceptance','essential');
 update public.companies set billing_status='active',is_test=true,billing_mode='test_simulated',seat_limit=10 where id=c;
 insert into public.company_members(company_id,user_id,role) values(c,a,'employee'),(c,b,'employee');
 select user_id into owner_id from private.platform_owner;insert into auth.sessions(id,user_id,aal,not_after) values(sid,owner_id,'aal2',clock_timestamp()+interval '1 hour');perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',owner_id,'session_id',sid,'aal','aal2')::text,true);execute 'set local role authenticated';perform public.platform_set_essential_test_plan(c,'essential_pro');
 perform set_config('request.jwt.claim.sub',boss::text,true);
 select id into l from public.essential_locations where company_id=c;d:=public.save_essential_department(c,l,'Production');
 select id into wa from public.company_workers where company_id=c and auth_user_id=a;select id into wb from public.company_workers where company_id=c and auth_user_id=b;
 perform public.assign_essential_worker(wa,l,d);perform public.assign_essential_worker(wb,l,d);
 s1:=public.save_essential_shift(c,wa,l,d,'2026-11-10 08:00-05','2026-11-10 16:00-05');s2:=public.save_essential_shift(c,wb,l,d,'2026-11-11 08:00-05','2026-11-11 16:00-05');
 open_shift:=public.save_essential_shift(c,null,l,d,'2026-11-12 08:00-05','2026-11-12 16:00-05');
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.request_essential_shift_change(s1,'swap',s2);
 if (select worker_id from public.scheduled_shifts where id=s1)<>wa then raise exception 'Request changed official assignment';end if;
 perform set_config('request.jwt.claim.sub',boss::text,true);
 denied:=false;begin perform public.review_essential_shift_request(r,true,'Try before colleague consent');exception when others then denied:=true;end;if not denied then raise exception 'Swap approved without colleague agreement';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.answer_essential_swap(r,true);
 perform set_config('request.jwt.claim.sub',boss::text,true);perform public.review_essential_shift_request(r,true,'Couverture vérifiée');
 if (select worker_id from public.scheduled_shifts where id=s1)<>wb or (select worker_id from public.scheduled_shifts where id=s2)<>wa then raise exception 'Atomic swap failed';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.request_essential_shift_change(open_shift,'claim');
 denied:=false;begin perform public.review_essential_shift_request(r,true,'My own request');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Self approval permitted';end if;
 perform set_config('request.jwt.claim.sub',boss::text,true);perform public.review_essential_shift_request(r,true,'Remplacement approuvé');
 if (select worker_id from public.scheduled_shifts where id=open_shift)<>wa then raise exception 'Vacant shift not filled';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);r:=public.request_essential_shift_change(open_shift,'release');
 perform set_config('request.jwt.claim.sub',boss::text,true);perform public.review_essential_shift_request(r,true,'Rendre le quart disponible');
 if (select worker_id from public.scheduled_shifts where id=open_shift) is not null then raise exception 'Release did not open the shift';end if;
 v_ids:=public.rotate_essential_shifts(c,wa,l,d,'2026-12-07',14,2,'[{"day":0,"start":"07:00","end":"15:00"},{"day":7,"start":"15:00","end":"23:00"}]',v_req);
 v_retry:=public.rotate_essential_shifts(c,wa,l,d,'2026-12-07',14,2,'[{"day":0,"start":"07:00","end":"15:00"},{"day":7,"start":"15:00","end":"23:00"}]',v_req);
 if cardinality(v_ids)<>4 or v_ids<>v_retry then raise exception 'Rotation/idempotence incorrect';end if;
 perform public.set_essential_minimum_staff(d,2);report:=public.essential_planning_report(c,'2026-11-10 08:00-05','2026-11-10 16:00-05');
 if (report->>'planned_gross_ms')::numeric<>28800000 or jsonb_array_length(report->'coverage_gaps')<>1 then raise exception 'Planned hours or coverage incorrect: %',report;end if;
 execute 'reset role';update public.company_members set status='disabled' where company_id=c and user_id=b;execute 'set local role authenticated';report:=public.essential_planning_report(c,'2026-11-10 08:00-05','2026-11-10 16:00-05');if (report->'coverage_gaps'->0->>'staffed')::integer<>0 then raise exception 'Disabled employee counted toward coverage';end if;
 v_pair:=public.create_essential_kiosk_pairing(c,l,'Borne 1');v_pair:=public.create_essential_kiosk_pairing(c,l,'Borne 2');
 execute 'reset role';
 if (select count(*) from private.kiosk_devices where company_id=c)<>2 then raise exception 'Pro terminal limit incorrect';end if;
end $$;
rollback;
